{"file_path":"src/lexer.js","content":"/**
 * The lexer. Turns UTF-8 source text into a stream of tokens following the
 * scanning rules described in the task: positions count from 1, tabs jump to
 * the next stop four columns wide, comments and strings nest or escape as
 * specified, and numbers reject any digit, letter or underscore run they did
 * not fully account for.
 */

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

const PUNCTS_2 = new Set(['==', '!=', '<=', '>=', '&&', '||', '->', '=>'])
const PUNCTS_1 = new Set(['+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.'])

function isDigit(c) {
  return c !== undefined && c >= '0' && c <= '9'
}

function isHexDigit(c) {
  return c !== undefined && (isDigit(c) || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F'))
}

function isBinDigit(c) {
  return c === '0' || c === '1'
}

function isOctDigit(c) {
  return c !== undefined && c >= '0' && c <= '7'
}

function isLetter(c) {
  return c !== undefined && ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'))
}

function isIdentStart(c) {
  return isLetter(c) || c === '_'
}

function isIdentCont(c) {
  return isLetter(c) || isDigit(c) || c === '_'
}

class LexError extends Error {
  constructor(line, col, message) {
    super(message)
    this.line = line
    this.col = col
  }
}

/**
 * Scans `source` into an array of `{ kind, text, line, col }` tokens, or
 * throws a `LexError` carrying the line and column of the first problem.
 */
export function lex(source) {
  const chars = Array.from(source)
  let i = 0
  let line = 1
  let col = 1

  function peek(offset = 0) {
    return chars[i + offset]
  }

  function advance() {
    const c = chars[i]
    i++
    if (c === '\n') {
      line++
      col = 1
    } else if (c === '\t') {
      col = Math.floor((col - 1) / 4) * 4 + 5
    } else {
      col++
    }
    return c
  }

  function fail(l, c, message) {
    throw new LexError(l, c, message)
  }

  // Consumes a maximal run of digits (as decided by `isDigitFn`), allowing a
  // single `_` between two digits of that same run.
  function scanDigitRun(isDigitFn) {
    let text = ''
    let hasDigit = false
    while (true) {
      const c = peek()
      if (isDigitFn(c)) {
        text += advance()
        hasDigit = true
      } else if (hasDigit && c === '_' && isDigitFn(peek(1))) {
        text += advance()
        text += advance()
      } else {
        break
      }
    }
    return text
  }

  function scanNumber() {
    const startLine = line
    const startCol = col
    let text = ''
    let invalid = false

    if (peek() === '0' && (peek(1) === 'x' || peek(1) === 'X')) {
      text += advance()
      text += advance()
      const digits = scanDigitRun(isHexDigit)
      text += digits
      if (digits === '') invalid = true
    } else if (peek() === '0' && (peek(1) === 'b' || peek(1) === 'B')) {
      text += advance()
      text += advance()
      const digits = scanDigitRun(isBinDigit)
      text += digits
      if (digits === '') invalid = true
    } else if (peek() === '0' && (peek(1) === 'o' || peek(1) === 'O')) {
      text += advance()
      text += advance()
      const digits = scanDigitRun(isOctDigit)
      text += digits
      if (digits === '') invalid = true
    } else {
      text += scanDigitRun(isDigit)
      if (peek() === '.' && isDigit(peek(1))) {
        text += advance()
        text += scanDigitRun(isDigit)
      }
      if (peek() === 'e' || peek() === 'E') {
        if (isDigit(peek(1))) {
          text += advance()
          text += scanDigitRun(isDigit)
        } else if ((peek(1) === '+' || peek(1) === '-') && isDigit(peek(2))) {
          text += advance()
          text += advance()
          text += scanDigitRun(isDigit)
        }
      }
    }

    if (isIdentCont(peek())) {
      invalid = true
      while (isIdentCont(peek())) text += advance()
    }

    if (invalid) fail(startLine, startCol, `invalid number ${text}`)

    return { kind: 'number', text, line: startLine, col: startCol }
  }

  function scanIdentifier() {
    const startLine = line
    const startCol = col
    let text = ''
    while (isIdentCont(peek())) text += advance()
    const kind = KEYWORDS.has(text) ? 'keyword' : 'ident'
    return { kind, text, line: startLine, col: startCol }
  }

  function scanString() {
    const startLine = line
    const startCol = col
    advance() // opening quote
    let value = ''
    while (true) {
      const c = peek()
      if (c === undefined) fail(startLine, startCol, 'unterminated string')
      if (c === '\n') fail(line, col, 'newline in string')
      if (c === '"') {
        advance()
        break
      }
      if (c === '\\') {
        const bsLine = line
        const bsCol = col
        advance() // backslash
        const e = peek()
        if (e === undefined) fail(startLine, startCol, 'unterminated string')
        switch (e) {
          case 'n':
            value += '\n'
            advance()
            break
          case 't':
            value += '\t'
            advance()
            break
          case 'r':
            value += '\r'
            advance()
            break
          case '\\':
            value += '\\'
            advance()
            break
          case '"':
            value += '"'
            advance()
            break
          case '0':
            value += '\0'
            advance()
            break
          case 'x': {
            advance() // 'x'
            let hex = ''
            for (let k = 0; k < 2; k++) {
              const h = peek()
              if (!isHexDigit(h)) fail(bsLine, bsCol, 'invalid escape \\x')
              hex += advance()
            }
            value += String.fromCharCode(parseInt(hex, 16))
            break
          }
          case 'u': {
            advance() // 'u'
            if (peek() !== '{') fail(bsLine, bsCol, 'invalid escape \\u')
            advance() // '{'
            let hex = ''
            while (isHexDigit(peek())) hex += advance()
            if (hex === '' || peek() !== '}') fail(bsLine, bsCol, 'invalid escape \\u')
            advance() // '}'
            const cp = parseInt(hex, 16)
            if (cp > 0x10ffff) fail(bsLine, bsCol, 'invalid escape \\u')
            value += String.fromCodePoint(cp)
            break
          }
          default:
            fail(bsLine, bsCol, `invalid escape \\${e}`)
        }
      } else {
        value += advance()
      }
    }
    return { kind: 'string', text: JSON.stringify(value), line: startLine, col: startCol }
  }

  function scanRawString() {
    const startLine = line
    const startCol = col
    advance() // 'r'
    advance() // '"'
    let value = ''
    while (true) {
      const c = peek()
      if (c === undefined) fail(startLine, startCol, 'unterminated string')
      if (c === '"') {
        advance()
        break
      }
      value += advance()
    }
    return { kind: 'rawstring', text: JSON.stringify(value), line: startLine, col: startCol }
  }

  function skipLineComment() {
    while (peek() !== undefined && peek() !== '\n') advance()
  }

  function skipBlockComment() {
    const startLine = line
    const startCol = col
    advance() // '/'
    advance() // '*'
    let depth = 1
    while (depth > 0) {
      const c = peek()
      if (c === undefined) fail(startLine, startCol, 'unterminated block comment')
      if (c === '/' && peek(1) === '*') {
        advance()
        advance()
        depth++
        continue
      }
      if (c === '*' && peek(1) === '/') {
        advance()
        advance()
        depth--
        continue
      }
      advance()
    }
  }

  function matchPunct() {
    const startLine = line
    const startCol = col
    const two = (peek() ?? '') + (peek(1) ?? '')
    if (PUNCTS_2.has(two)) {
      advance()
      advance()
      return { kind: 'punct', text: two, line: startLine, col: startCol }
    }
    const one = peek()
    if (one !== undefined && PUNCTS_1.has(one)) {
      advance()
      return { kind: 'punct', text: one, line: startLine, col: startCol }
    }
    return null
  }

  const tokens = []
  while (i < chars.length) {
    const c = peek()
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
      advance()
      continue
    }
    if (c === '/' && peek(1) === '/') {
      skipLineComment()
      continue
    }
    if (c === '/' && peek(1) === '*') {
      skipBlockComment()
      continue
    }
    if (c === '"') {
      tokens.push(scanString())
      continue
    }
    if (c === 'r' && peek(1) === '"') {
      tokens.push(scanRawString())
      continue
    }
    if (isDigit(c)) {
      tokens.push(scanNumber())
      continue
    }
    if (isIdentStart(c)) {
      tokens.push(scanIdentifier())
      continue
    }
    const punct = matchPunct()
    if (punct) {
      tokens.push(punct)
      continue
    }
    fail(line, col, `unexpected character ${c}`)
  }
  return tokens
}
"}

