const PUNCTS_2 = new Set(['==', '!=', '<=', '>=', '&&', '||', '->', '=>'])
const PUNCTS_1 = new Set(['+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.'])

function isDigit(c) {
  return c !== undefined && c >= '0' && c <= '9'
}

function isHexDigit(c) {
  return c !== undefined && (isDigit(c) || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F'))
}

function isBinDigit(c) {
  return c === '0' || c === '1'
}

function isOctDigit(c) {
  return c !== undefined && c >= '0' && c <= '7'
}

function isLetter(c) {
  return c !== undefined && ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'))
}

function isIdentStart(c) {
  return isLetter(c) || c === '_'
}

function isIdentCont(c) {
  return isLetter(c) || isDigit(c) || c === '_'
}

class LexError extends Error {
  constructor(line, col, message) {
    super(message)
    this.line = line
    this.col = col
