{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js tokens` prints every token of the source read
 * from standard input with its position, and `node src/cli.js stats` counts the
 * tokens by kind.
 */

import { lex } from './lexer.js'

const KIND_ORDER = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

function readStdin() {
  return new Promise((resolve, reject) => {
    const chunks = []
    process.stdin.on('data', (d) => chunks.push(d))
    process.stdin.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')))
    process.stdin.on('error', reject)
  })
}

async function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'tokens' && mode !== 'stats')) {
    process.stderr.write('error: usage: cli.js tokens|stats\n')
    process.exit(2)
    return
  }

  const source = await readStdin()

  let tokens
  try {
    tokens = lex(source)
  } catch (e) {
    process.stderr.write(`error: ${e.line}:${e.col}: ${e.message}\n`)
    process.exit(2)
    return
  }

  let output = ''
  if (mode === 'tokens') {
    for (const t of tokens) output += `${t.line}:${t.col} ${t.kind} ${t.text}\n`
  } else {
    const counts = Object.fromEntries(KIND_ORDER.map((k) => [k, 0]))
    for (const t of tokens) counts[t.kind]++
    for (const k of KIND_ORDER) output += `${k} ${counts[k]}\n`
    output += `total ${tokens.length}\n`
  }
  process.stdout.write(output)
  process.exit(0)
}

main()
"}

